	private static boolean compatible(BindingSet first, BindingSet second) {
		for (String name : first.getBindingNames()) {
			Value firstValue = first.getValue(name);
			Value secondValue = second.getValue(name);
			if (firstValue != null && secondValue != null && !firstValue.equals(secondValue)) {
				return false;
			}
		}
		for (String name : second.getBindingNames()) {
			Value firstValue = first.getValue(name);
			Value secondValue = second.getValue(name);
			if (firstValue != null && secondValue != null && !firstValue.equals(secondValue)) {
				return false;
			}
		}
		return true;
	}

